window.BC = window.BC || {};
// Trees are built from blocks. `shape` picks a builder in world.js.
BC.TREES = [
  { id: 'sugar_maple', name: 'Sugar Maple', sci: 'Acer saccharum', family: 'Sapindaceae (soapberry family)',
    biomes: ['temperate'], soils: ['alfisol', 'compost'], ph: [5.5, 7.3], water: 'med', sun: 'part', shape: 'broad', log: 'oak', leaf: '#d8702a', height: [5, 7], grow: 360,
    seed: 'maple samaras (helicopters)',
    teach: 'Its winged seeds (samaras) spin like helicopter blades so the wind carries them away from the parent\'s shade.',
    facts: ['Maple syrup is sap boiled down 40 to 1. The sap runs only in late winter, when freezing nights and thawing days pump it up and down the trunk.',
      'Its leaves turn orange and red because the tree makes anthocyanin pigments as a sunscreen while it pulls nitrogen back out of the leaf.',
      'A mature sugar maple is one of the most shade-tolerant trees; its seedlings can wait decades in the understorey for a gap.'] },
  { id: 'white_oak', name: 'White Oak', sci: 'Quercus alba', family: 'Fagaceae (beech family)',
    biomes: ['temperate'], soils: ['alfisol', 'mollisol', 'compost'], ph: [5.5, 7.0], water: 'med', sun: 'full', shape: 'broad', log: 'oak', leaf: '#4f8a32', height: [6, 8], grow: 420,
    seed: 'acorns',
    teach: 'Oaks support more life than any other North American tree: over 500 species of caterpillar, which in turn feed nearly every songbird chick.',
    facts: ['Acorns are produced in boom "mast years" every few years so that squirrels and jays cannot eat them all. Jays bury thousands and forget many: that is how oaks move uphill.',
      'A white oak can live 300 to 600 years. Barrels for wine and whiskey are made from it because its wood cells are plugged with tyloses, making it watertight.',
      'White oak acorns sprout the autumn they fall; red oak acorns wait until spring. The two groups also differ in leaf tips: rounded for white, bristled for red.'] },
  { id: 'paper_birch', name: 'Paper Birch', sci: 'Betula papyrifera', family: 'Betulaceae (birch family)',
    biomes: ['boreal', 'temperate'], soils: ['spodosol', 'alfisol', 'compost'], ph: [5.0, 6.5], water: 'med', sun: 'full', shape: 'broad', log: 'birch', leaf: '#8ab83a', height: [5, 7], grow: 240,
    seed: 'birch catkin seeds',
    teach: 'A pioneer tree. Its tiny winged seeds blow in after fire or logging, and its white bark reflects winter sun so the trunk does not crack from freeze and thaw.',
    facts: ['The bark is waterproof and peels in sheets; Anishinaabe and other peoples built canoes, baskets and wigwam covers from it.',
      'It is short-lived (60 to 80 years) and is eventually shaded out by spruce and fir, a textbook case of succession.',
      'Birch pollen is a major spring allergen; a single catkin releases millions of grains.'] },
  { id: 'black_spruce', name: 'Black Spruce', sci: 'Picea mariana', family: 'Pinaceae (pine family)',
    biomes: ['boreal', 'wetland'], soils: ['spodosol', 'histosol'], ph: [3.5, 5.5], water: 'high', sun: 'full', shape: 'conifer', log: 'spruce', leaf: '#2e5a3a', height: [6, 9], grow: 420,
    seed: 'spruce cone seeds',
    teach: 'The tree of the muskeg and permafrost. Its roots stay in the top 20 cm of soil above the frozen ground, so it grows slowly and narrow.',
    facts: ['Lower branches that touch the moss take root and grow into new trunks (layering), forming clonal clumps.',
      'Its cones stay closed on the tree for years and open after fire, re-seeding the burn.',
      'Spruce needles are rich in vitamin C; spruce tip tea saved Jacques Cartier\'s crew from scurvy in 1536.'] },
  { id: 'jack_pine', name: 'Jack Pine', sci: 'Pinus banksiana', family: 'Pinaceae (pine family)',
    biomes: ['boreal'], soils: ['spodosol', 'aridisol'], ph: [4.5, 6.5], water: 'low', sun: 'full', shape: 'conifer', log: 'spruce', leaf: '#4a7a3a', height: [5, 7], grow: 360,
    seed: 'jack pine cone seeds',
    teach: 'Its cones are glued shut with resin and open only above 50 °C: a wildfire is the key. Jack pine forests need fire to reproduce.',
    facts: ['The endangered Kirtland\'s warbler nests only under young jack pines 5 to 20 years after a fire; fire suppression nearly wiped it out.',
      'It grows on the poorest, driest sand where nothing else can, with needles in bundles of two.',
      'Serotiny (fire-opened cones) evolved independently in pines, eucalypts and banksias on three continents.'] },
  { id: 'bur_oak', name: 'Bur Oak', sci: 'Quercus macrocarpa', family: 'Fagaceae (beech family)',
    biomes: ['prairie', 'temperate'], soils: ['mollisol', 'alfisol', 'compost'], ph: [6.0, 8.0], water: 'low', sun: 'full', shape: 'broad', log: 'oak', leaf: '#5f8a3a', height: [5, 7], grow: 480,
    seed: 'bur oak acorns (fringed cap)',
    teach: 'The only oak that can live on the open prairie. Its thick corky bark shrugs off grass fires that kill every other tree seedling.',
    facts: ['It has the largest acorns of any North American oak, with a shaggy fringed cap, hence "bur".',
      'A seedling spends its first years growing a taproot down, not a trunk up, to reach water below the grass roots.',
      'Scattered bur oaks over grass form an oak savanna, one of the rarest ecosystems in the Midwest.'] },
  { id: 'cottonwood', name: 'Eastern Cottonwood', sci: 'Populus deltoides', family: 'Salicaceae (willow family)',
    biomes: ['prairie', 'wetland'], soils: ['mollisol', 'gley', 'alfisol'], ph: [6.0, 8.0], water: 'high', sun: 'full', shape: 'tall', log: 'birch', leaf: '#7fb040', height: [8, 11], grow: 240,
    seed: 'cottonwood fluff seeds',
    teach: 'The fastest-growing tree on the plains, up to 2 metres a year, found only where its roots can reach a river or groundwater.',
    facts: ['Trees are male or female. In June the females release clouds of cotton-wrapped seeds that must land on wet mud within days or die.',
      'The flat leaf stalks make the leaves tremble in the slightest breeze, which may help them shed heat.',
      'Lewis and Clark\'s expedition burned cottonwood for fuel across the treeless plains and made dugout canoes from its trunks.'] },
  { id: 'saguaro', name: 'Saguaro', sci: 'Carnegiea gigantea', family: 'Cactaceae (cactus family)',
    biomes: ['desert'], soils: ['aridisol', 'sand_subsoil'], ph: [7.0, 8.5], water: 'low', sun: 'full', shape: 'saguaro', log: 'cactus', leaf: null, height: [6, 9], grow: 600,
    seed: 'saguaro seeds',
    teach: 'The giant of the Sonoran Desert grows only there. It takes 10 years to reach 4 cm, 50 to 75 years to grow its first arm, and can live 200 years.',
    facts: ['Its pleated skin expands like an accordion to store up to 750 litres of rain, and a shallow root web as wide as the plant is tall catches every drop.',
      'The white flowers open at night and are pollinated by lesser long-nosed bats, then by doves and bees at dawn.',
      'Seedlings survive only in the shade of a nurse plant, usually a palo verde. The Tohono O\'odham harvest the red fruit each June to start their new year.'] },
  { id: 'mesquite', name: 'Velvet Mesquite', sci: 'Prosopis velutina', family: 'Fabaceae (pea family)',
    biomes: ['desert'], soils: ['aridisol', 'sand_subsoil'], ph: [7.0, 8.5], water: 'low', sun: 'full', shape: 'spreading', log: 'mesquite', leaf: '#6f8a3a', height: [3, 4], grow: 360, nFix: true,
    seed: 'mesquite pods',
    teach: 'A desert legume. Its roots reach deeper than any other plant (a record of 53 metres down a mine shaft) and fix nitrogen, so the soil beneath it is a fertile island.',
    facts: ['The sweet pods were a staple food of desert peoples, ground into flour; they are rich in protein and sugar.',
      'Mesquite wood burns hot and slow, which is why it is the classic barbecue fuel of the South-west.',
      'Birds, cacti and wildflowers cluster under mesquite canopies for shade, water and the extra nitrogen.'] },
  { id: 'palo_verde', name: 'Foothill Palo Verde', sci: 'Parkinsonia microphylla', family: 'Fabaceae (pea family)',
    biomes: ['desert'], soils: ['aridisol', 'sand_subsoil'], ph: [7.0, 8.5], water: 'low', sun: 'full', shape: 'spreading', log: 'paloverde', leaf: '#9ab84a', height: [3, 5], grow: 320, nFix: true,
    seed: 'palo verde seeds',
    teach: 'Palo verde means green stick. In drought it drops its tiny leaves and photosynthesises through its green bark instead.',
    facts: ['It is the nurse plant of the saguaro: baby cacti survive the sun and frost only in its filtered shade.',
      'Arizona\'s state tree. In April it is covered in yellow pea flowers that feed hundreds of native bee species.',
      'Its seeds are so hard that they germinate best after a flash flood tumbles them against rocks (scarification).'] },
  { id: 'kapok', name: 'Kapok (Ceiba)', sci: 'Ceiba pentandra', family: 'Malvaceae (mallow family)',
    biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [5.0, 6.5], water: 'high', sun: 'full', shape: 'kapok', log: 'tropical', leaf: '#3a8a3a', height: [12, 15], grow: 540,
    seed: 'kapok seeds in silky fibre',
    teach: 'An emergent giant that towers 60 to 70 m above the canopy, standing on buttress roots several metres tall because rainforest soil is too thin for a deep taproot.',
    facts: ['Bats pollinate its night flowers; the seed pods burst into cotton-like kapok fibre once used to stuff life jackets and mattresses.',
      'It was the sacred world tree of the Maya, linking the underworld, earth and sky.',
      'A single kapok can host thousands of epiphytes, frogs, ants and birds, a vertical city.'] },
  { id: 'brazil_nut', name: 'Brazil Nut Tree', sci: 'Bertholletia excelsa', family: 'Lecythidaceae',
    biomes: ['rainforest'], soils: ['oxisol'], ph: [4.5, 6.0], water: 'high', sun: 'full', shape: 'tall', log: 'tropical', leaf: '#2f7a2f', height: [10, 13], grow: 540,
    seed: 'Brazil nuts',
    teach: 'A tree that cannot be farmed. Only large orchid bees can force open its flowers, and only the agouti, a rodent, can gnaw open the cannonball fruit to plant the seeds.',
    facts: ['The bees need a rainforest orchid to complete their mating dance, so Brazil nuts come only from intact forest.',
      'The woody fruit weighs up to 2 kg and falls 50 m; harvesters work in helmets during the rainy season.',
      'The nuts are the richest food source of selenium known; a single nut gives a day\'s supply.'] },
  { id: 'bald_cypress', name: 'Bald Cypress', sci: 'Taxodium distichum', family: 'Cupressaceae (cypress family)',
    biomes: ['wetland'], soils: ['histosol', 'gley'], ph: [5.0, 7.0], water: 'aquatic', sun: 'full', shape: 'cypress', log: 'cypress', leaf: '#6a8a3a', height: [8, 11], grow: 480,
    seed: 'cypress cone seeds',
    teach: 'A conifer that drops its needles each autumn (hence "bald") and grows standing in water, sending up woody knees that may help it breathe or stay upright.',
    facts: ['Some bald cypresses in North Carolina are over 2,600 years old, the oldest known trees in eastern North America.',
      'The flared, buttressed base braces the tree in soft mud; the wood is so rot-resistant it is called the eternal wood.',
      'Its seeds germinate only on wet soil that is not flooded, which is why cypress swamps need occasional droughts to regenerate.'] },
  { id: 'black_willow', name: 'Black Willow', sci: 'Salix nigra', family: 'Salicaceae (willow family)',
    biomes: ['wetland', 'temperate'], soils: ['gley', 'histosol', 'alfisol'], ph: [5.5, 7.5], water: 'high', sun: 'full', shape: 'willow', log: 'birch', leaf: '#8ab050', height: [5, 7], grow: 200,
    seed: 'willow cuttings',
    teach: 'Willow bark contains salicin, the compound that led to aspirin. People chewed it for pain for over 3,000 years.',
    facts: ['A willow branch stuck in wet mud will root in days; the stems carry their own rooting hormone, and gardeners soak cuttings in willow water.',
      'Dense fibrous roots hold riverbanks together, which is why engineers plant willow stakes to stop erosion.',
      'Its fluffy seeds live only a day or two; they must land on bare wet mud immediately.'] },
  // ---------- additional trees ----------
  { id: 'american_beech', name: 'American Beech', sci: 'Fagus grandifolia', family: 'Fagaceae (beech family)',
    biomes: ['temperate'], soils: ['alfisol', 'compost'], ph: [5.0, 6.5], water: 'med', sun: 'part', shape: 'broad', log: 'birch', leaf: '#7fa83a', height: [6, 8], grow: 480,
    seed: 'beechnuts',
    teach: 'Smooth grey bark that never furrows, and leaves that cling, papery and pale, all winter. Beech is the most shade-tolerant big tree of the eastern forest and the last to take over an old woodland.',
    facts: ['Beech roots send up suckers, so one tree can become a grove of clones.', 'Passenger pigeons once fed on beechnut masts in flocks that darkened the sky; the pigeon is extinct, the trees remain.', 'Carving initials into beech bark scars it for life, which is why old beeches near towns are covered in names.'] },
  { id: 'eastern_hemlock', name: 'Eastern Hemlock', sci: 'Tsuga canadensis', family: 'Pinaceae (pine family)',
    biomes: ['temperate', 'boreal'], soils: ['alfisol', 'spodosol'], ph: [4.5, 6.0], water: 'high', sun: 'shade', shape: 'conifer', log: 'spruce', leaf: '#2f6a40', height: [8, 11], grow: 540,
    seed: 'hemlock cone seeds',
    teach: 'A conifer that grows in deep shade along cool ravines and streams, cooling the water for trout. It can wait 200 years in the understorey and live 800.',
    facts: ['Not the poison hemlock that killed Socrates; that is an unrelated herb. The tree got the name because crushed needles smell similar.', 'The hemlock woolly adelgid, a tiny insect from Japan, is killing hemlocks across the Appalachians. Streams warm when they die.', 'Tannin from hemlock bark tanned most of America\'s leather in the 1800s; whole forests were stripped and left to rot.'] },
  { id: 'flowering_dogwood', name: 'Flowering Dogwood', sci: 'Cornus florida', family: 'Cornaceae (dogwood family)',
    biomes: ['temperate'], soils: ['alfisol', 'compost'], ph: [5.5, 6.5], water: 'med', sun: 'part', shape: 'broad', log: 'oak', leaf: '#e8dcc8', height: [3, 4], grow: 240,
    seed: 'dogwood drupes',
    teach: 'The white "petals" are bracts, modified leaves, around a cluster of tiny true flowers. An understorey tree that blooms before the canopy leafs out.',
    facts: ['Its red autumn berries are rich in fat and feed migrating birds just when they need fuel.', 'Dogwood leaf litter is unusually high in calcium and decomposes fast, improving the soil beneath it.', 'Dogwood anthracnose, a fungal disease, has thinned wild dogwoods since the 1980s, especially in shady, damp sites.'] },
  { id: 'shagbark_hickory', name: 'Shagbark Hickory', sci: 'Carya ovata', family: 'Juglandaceae (walnut family)',
    biomes: ['temperate'], soils: ['alfisol', 'mollisol'], ph: [6.0, 7.0], water: 'med', sun: 'full', shape: 'tall', log: 'oak', leaf: '#8fa83a', height: [8, 10], grow: 540,
    seed: 'hickory nuts',
    teach: 'Bark peels away in long shaggy plates, and endangered Indiana bats roost under them. The nuts are the sweetest of the hickories.',
    facts: ['Hickory wood is strong and springy: axe handles, baseball bats and the smoke for bacon.', 'Like oaks, hickories mast: a huge nut crop some years, almost none in others, so squirrels cannot keep up.', 'A hickory grows a taproot a metre deep before it is knee-high, which is why they are hard to transplant.'] },
  { id: 'desert_ironwood', name: 'Desert Ironwood', sci: 'Olneya tesota', family: 'Fabaceae (pea family)',
    biomes: ['desert'], soils: ['aridisol', 'sand_subsoil'], ph: [7.0, 8.5], water: 'low', sun: 'full', shape: 'spreading', log: 'mesquite', leaf: '#6f8a6a', height: [3, 5], grow: 600, nFix: true,
    seed: 'ironwood seeds',
    teach: 'The oldest tree of the Sonoran Desert, living 800 years or more. Its canopy is a nursery: over 200 plant species, including young saguaros, start life in its shade.',
    facts: ['The wood is so dense it sinks in water and dulls saws; Seri carvers shape it into animals.', 'As a legume it fixes nitrogen, so soil under an ironwood is richer than the open desert.', 'It grows only where winter frost is rare, so its range marks the true Sonoran Desert on a map.'] },
  { id: 'joshua_tree', name: 'Joshua Tree', sci: 'Yucca brevifolia', family: 'Asparagaceae',
    biomes: ['desert'], soils: ['aridisol', 'sand_subsoil'], ph: [7.0, 8.5], water: 'low', sun: 'full', shape: 'spreading', log: 'paloverde', leaf: '#5a8a5a', height: [4, 6], grow: 600,
    seed: 'Joshua tree seeds',
    teach: 'Not a tree but a giant yucca, pollinated only by the yucca moth, which lays eggs in the flower and deliberately packs pollen onto the stigma so its larvae will have seeds to eat.',
    facts: ['Each branch grows until it flowers, then forks, so a tree\'s shape records its flowering history.', 'Mormon settlers named it for the prophet Joshua raising his arms. It grows only in the Mojave Desert.', 'Climate models suggest most of Joshua Tree National Park will be too hot for Joshua trees by 2100.'] },
  { id: 'date_palm', name: 'Date Palm', sci: 'Phoenix dactylifera', family: 'Arecaceae (palm family)',
    biomes: ['desert'], soils: ['aridisol', 'gley'], ph: [7.0, 8.5], water: 'high', sun: 'full', shape: 'palm', log: 'palm', leaf: '#6a9a4a', height: [7, 10], grow: 480,
    seed: 'date stones',
    teach: 'The tree of the oasis: "feet in water, head in fire". Palms are not true trees; the trunk is packed fibre with no growth rings and cannot heal a wound.',
    facts: ['Cultivated for at least 6,000 years in Mesopotamia; a single tree gives 70 kg of dates a year for a century.', 'Date palms are male or female. Growers hand-pollinate females, one male tree serving fifty.', 'A 2,000-year-old date seed from Masada was germinated in 2005 and grew into a healthy male palm named Methuselah.'] },
  { id: 'rubber_tree', name: 'Rubber Tree', sci: 'Hevea brasiliensis', family: 'Euphorbiaceae (spurge family)',
    biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [4.5, 6.0], water: 'high', sun: 'full', shape: 'tall', log: 'tropical', leaf: '#3f8a3a', height: [9, 12], grow: 480,
    seed: 'rubber tree seeds',
    teach: 'Cut the bark and white latex bleeds out: the tree\'s defence against insects, and the source of natural rubber for every aircraft tyre and surgical glove.',
    facts: ['Native to the Amazon, where leaf blight keeps trees far apart. Seeds smuggled to Kew in 1876 founded the plantations of Asia, where the blight does not exist.', 'Tappers cut a thin spiral every other day before dawn, when latex flows best; a tree yields for 25 years.', 'The seed pods explode with a crack, throwing seeds 30 m.'] },
  { id: 'mahogany', name: 'Big-leaf Mahogany', sci: 'Swietenia macrophylla', family: 'Meliaceae (mahogany family)',
    biomes: ['rainforest'], soils: ['oxisol'], ph: [5.0, 6.5], water: 'high', sun: 'full', shape: 'tall', log: 'cypress', leaf: '#2f7a35', height: [10, 13], grow: 600,
    seed: 'winged mahogany seeds',
    teach: 'The most valuable timber of the tropics, so heavily logged that it is now protected under the CITES treaty. Trees grow scattered, one per hectare, which makes loggers cut roads to every one.',
    facts: ['Woody fruits the size of a fist open on the tree to release winged seeds that spin away.', 'It needs disturbance to regenerate: seedlings only thrive in gaps left by fallen giants or floods.', 'Chippendale furniture and Spanish galleons were mahogany. Today most "mahogany" sold is a different, unrelated wood.'] },
  { id: 'acai_palm', name: 'Açaí Palm', sci: 'Euterpe oleracea', family: 'Arecaceae (palm family)',
    biomes: ['rainforest', 'wetland'], soils: ['oxisol', 'histosol', 'gley'], ph: [4.5, 6.5], water: 'aquatic', sun: 'part', shape: 'palm', log: 'palm', leaf: '#4f9a4a', height: [8, 11], grow: 360,
    seed: 'açaí seeds',
    teach: 'A slender palm of the Amazon floodplain that grows in clumps and tolerates months with its roots under water. The purple berries are 90% seed.',
    facts: ['Local people have eaten açaí for centuries; the global smoothie boom raised prices so much that some Amazonian families could no longer afford their staple food.', 'Harvesters climb 20 m trunks with a loop of palm leaf around their feet.', 'Heart of palm is the growing tip; cutting it kills the stem, but açaí clumps regrow from the base, unlike single-stemmed palms.'] },
  { id: 'tamarack', name: 'Tamarack', sci: 'Larix laricina', family: 'Pinaceae (pine family)',
    biomes: ['boreal', 'wetland'], soils: ['histosol', 'spodosol'], ph: [4.0, 6.0], water: 'high', sun: 'full', shape: 'conifer', log: 'spruce', leaf: '#b8c85a', height: [6, 9], grow: 420,
    seed: 'tamarack cone seeds',
    teach: 'A conifer that is not evergreen: its soft needles turn gold and drop every autumn. Losing needles saves water when the ground is frozen solid.',
    facts: ['It grows in bogs on floating mats of sphagnum where no other tree survives, and ranges further north than any other North American tree.', 'The Ojibwe word adikameg gives us the name. Its roots were used to sew birch-bark canoes.', 'Larch wood resists rot in water; Venice stands on larch piles.'] },
  { id: 'quaking_aspen', name: 'Quaking Aspen', sci: 'Populus tremuloides', family: 'Salicaceae (willow family)',
    biomes: ['boreal', 'temperate'], soils: ['spodosol', 'alfisol', 'mollisol'], ph: [5.0, 7.0], water: 'med', sun: 'full', shape: 'tall', log: 'birch', leaf: '#a8c848', height: [7, 10], grow: 240,
    seed: 'aspen root sprouts',
    teach: 'An aspen grove is usually one organism: the trunks are stems of a single root system. Pando in Utah has 47,000 trunks, weighs 6,000 tonnes and may be 14,000 years old.',
    facts: ['Flat leaf stalks make the leaves tremble in any breeze, hence "quaking". The green bark photosynthesises in winter.', 'Aspen is the most widely distributed tree in North America, from Alaska to Mexico.', 'Beavers, elk and moose eat it; without wolves to keep elk moving, Yellowstone\'s aspens stopped regenerating for 70 years.'] },
  { id: 'balsam_fir', name: 'Balsam Fir', sci: 'Abies balsamea', family: 'Pinaceae (pine family)',
    biomes: ['boreal'], soils: ['spodosol', 'histosol'], ph: [4.0, 6.0], water: 'high', sun: 'shade', shape: 'conifer', log: 'spruce', leaf: '#2a6a4a', height: [7, 10], grow: 420,
    seed: 'fir cone seeds',
    teach: 'The classic Christmas tree: flat needles, a perfect spire, and resin blisters on the bark that smell of the north woods. Fir cones stand upright and fall apart on the tree, so you never find one on the ground.',
    facts: ['Spruce budworm caterpillars strip fir forests in outbreaks every 30 to 40 years; the dead stands then burn and the cycle restarts.', 'Canada balsam resin is so optically clear it was used to glue microscope lenses.', 'Moose browse fir in winter, and snowshoe hares girdle seedlings under the snow.'] },
  { id: 'red_maple', name: 'Red Maple', sci: 'Acer rubrum', family: 'Sapindaceae (soapberry family)',
    biomes: ['wetland', 'temperate'], soils: ['gley', 'histosol', 'alfisol'], ph: [4.5, 7.0], water: 'high', sun: 'full', shape: 'broad', log: 'oak', leaf: '#d8402a', height: [6, 9], grow: 300,
    seed: 'red maple samaras',
    teach: 'Red in every season: red buds in winter, red flowers in March, red leaf stalks in summer, scarlet leaves in autumn. It is now the most common tree in the eastern United States.',
    facts: ['It thrives in swamps and on dry ridges alike, and fire suppression has let it spread into oak forests everywhere.', 'Its flowers open before the leaves and are among the first food for bees in spring.', 'Red maple leaves are toxic to horses when wilted, destroying their red blood cells.'] },
  { id: 'red_mangrove', name: 'Red Mangrove', sci: 'Rhizophora mangle', family: 'Rhizophoraceae',
    biomes: ['wetland'], soils: ['gley', 'histosol'], ph: [6.0, 8.0], water: 'aquatic', sun: 'full', shape: 'cypress', log: 'mesquite', leaf: '#3a7a3a', height: [4, 6], grow: 420,
    seed: 'mangrove propagules',
    teach: 'A tree that walks into the sea on stilt roots. Its seeds germinate while still on the branch, then drop as pencil-shaped seedlings that float until they strike mud and root.',
    facts: ['Mangroves filter salt at the root and excrete the rest through old leaves. The roots take in oxygen through pores above the water line.', 'Mangrove forests shelter juvenile fish, trap sediment, and absorbed much of the 2004 tsunami\'s energy where they had not been cleared for shrimp farms.', 'Per hectare, mangrove mud stores four times more carbon than rainforest.'] },
  { id: 'neem', name: 'Neem', sci: 'Azadirachta indica', family: 'Meliaceae (mahogany family)',
    biomes: ['rainforest', 'desert'], soils: ['oxisol', 'aridisol', 'compost'], ph: [5.5, 8.0], water: 'low', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#3a8a40', height: [6, 8], grow: 420,
    seed: 'neem seeds',
    teach: 'The village pharmacy of India. Its seeds hold azadirachtin, which stops insects feeding and moulting; the oil is the most widely used botanical pesticide in the world. Twigs are chewed as toothbrushes.',
    facts: ['Locusts will starve rather than eat neem leaves; the compound was identified when a 1959 Sudanese locust plague left neem trees untouched.', 'It grows in poor, dry soil and is planted across the Sahel against desertification.', 'Neem cake, the pressed seed, is a fertiliser that also suppresses nematodes.'] },
  // ---------- fruit trees (20): shake or snip the leaves for fruit ----------
  { id: 'apple', name: 'Apple', sci: 'Malus domestica', family: 'Rosaceae (rose family)', biomes: ['temperate', 'prairie', 'boreal'], soils: ['alfisol', 'mollisol', 'compost'], ph: [6.0, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#4f8a38', fruitColor: '#d8303a', height: [4, 5], grow: 420, seed: 'apple pips', fruit: { name: 'apples', price: 3 },
    teach: 'Every apple variety is a clone: pips grow a stranger, so Honeycrisp, Fuji and Granny Smith are all cuttings grafted onto rootstock. The wild ancestor still grows in the mountains of Kazakhstan.',
    facts: ['Johnny Appleseed planted pips, not grafts, so his orchards grew sour cider apples: the frontier drank its apples.', 'An apple needs a different variety nearby for pollination; one tree alone sets little fruit.', 'Chill hours matter: most apples need 500 to 1,000 hours below 7 °C in winter to flower, which is why they fail in the tropics.'] },
  { id: 'pear', name: 'European Pear', sci: 'Pyrus communis', family: 'Rosaceae (rose family)', biomes: ['temperate', 'prairie'], soils: ['alfisol', 'mollisol', 'compost'], ph: [6.0, 7.2], water: 'med', sun: 'full', shape: 'tall', log: 'oak', leaf: '#3f7a30', fruitColor: '#c8c060', height: [5, 7], grow: 450, seed: 'pear seeds', fruit: { name: 'pears', price: 3 },
    teach: 'Pears ripen from the inside out and are picked hard: left on the tree they go mealy at the core. A pear tree lives 200 years and the old saying was "plant pears for your heirs".',
    facts: ['Pear wood is so fine-grained it was used for woodcut printing blocks and rulers.', 'Fire blight, a bacterial disease, blackens shoots as if scorched; prune it out 30 cm below the damage and disinfect the blade.', 'Asian pears are a different species, round and crisp, picked ripe.'] },
  { id: 'peach', name: 'Peach', sci: 'Prunus persica', family: 'Rosaceae (rose family)', biomes: ['temperate', 'prairie', 'desert'], soils: ['alfisol', 'mollisol', 'aridisol', 'compost'], ph: [6.0, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#5a9a3a', fruitColor: '#f0a060', height: [3, 4], grow: 360, seed: 'peach pits', fruit: { name: 'peaches', price: 4 },
    teach: 'Peaches fruit on last year\'s wood, so a peach is pruned hard every winter into an open vase to keep new shoots coming and light in the middle. A neglected peach fruits only at the tips.',
    facts: ['Native to China, carried west on the Silk Road; the Latin name means Persian apple.', 'Peach leaf curl is a fungus that infects as buds swell; a copper spray in late winter is the only time it can be stopped.', 'Thin the fruit to a hand-width apart or you get a hundred small peaches and a broken limb.'] },
  { id: 'cherry', name: 'Sweet Cherry', sci: 'Prunus avium', family: 'Rosaceae (rose family)', biomes: ['temperate', 'boreal'], soils: ['alfisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'broad', log: 'birch', leaf: '#3a7a2a', fruitColor: '#9a1020', height: [5, 7], grow: 450, seed: 'cherry stones', fruit: { name: 'cherries', price: 4 },
    teach: 'Birds will take every cherry the day before you planned to. Netting, or a sour cherry that birds like less, is the only answer. The bark peels in horizontal bands with breathing pores called lenticels.',
    facts: ['Cherry blossom in Japan (hanami) is a national festival; the Washington trees were a gift from Tokyo in 1912.', 'Rain at harvest splits the fruit: the skin cannot stretch as fast as the flesh swells.', 'Cherry wood is the classic furniture timber, darkening to deep red with age.'] },
  { id: 'plum', name: 'European Plum', sci: 'Prunus domestica', family: 'Rosaceae (rose family)', biomes: ['temperate', 'prairie'], soils: ['alfisol', 'mollisol', 'compost'], ph: [5.5, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#4a8a3a', fruitColor: '#5a2a7a', height: [4, 5], grow: 400, seed: 'plum stones', fruit: { name: 'plums', price: 3 },
    teach: 'Plums bloom early and lose their crop to a late frost more often than any other fruit. The waxy bloom on the skin is natural yeast; it is why plums ferment so readily into slivovitz and umeshu.',
    facts: ['Prunes are dried plums of a few high-sugar varieties.', 'Plum curculio, a weevil, cuts a crescent in each young fruit to lay an egg; shake the tree over a sheet at dawn and the beetles drop.', 'Damsons and greengages are old European plums; most American plums are hybrids with the native wild plum.'] },
  { id: 'pawpaw', name: 'Pawpaw', sci: 'Asimina triloba', family: 'Annonaceae (custard-apple family)', biomes: ['temperate', 'wetland'], soils: ['alfisol', 'gley', 'compost'], ph: [5.5, 7.0], water: 'high', sun: 'shade', shape: 'broad', log: 'oak', leaf: '#3a8a3a', fruitColor: '#a8b848', height: [4, 5], grow: 420, seed: 'pawpaw seeds', fruit: { name: 'pawpaws', price: 5 },
    teach: 'The largest fruit native to North America, tasting of banana and mango, growing wild in the shade of eastern river bottoms. It is pollinated by flies and beetles, not bees: the flowers are maroon and smell faintly of carrion.',
    facts: ['The fruit bruises in a day and never reached supermarkets, which is why most people have never eaten one.', 'The zebra swallowtail butterfly lays only on pawpaw.', 'Its seeds are spread by raccoons and foxes; before them, probably by mastodons.'] },
  { id: 'persimmon', name: 'American Persimmon', sci: 'Diospyros virginiana', family: 'Ebenaceae (ebony family)', biomes: ['temperate', 'prairie'], soils: ['alfisol', 'mollisol', 'compost'], ph: [6.0, 7.5], water: 'low', sun: 'full', shape: 'tall', log: 'oak', leaf: '#4a7a3a', fruitColor: '#e07a30', height: [5, 7], grow: 480, seed: 'persimmon seeds', fruit: { name: 'persimmons', price: 4 },
    teach: 'Eaten a day early it puckers your whole mouth with tannin; eaten soft after frost it is pudding. The wood is true ebony, once used for golf club heads.',
    facts: ['Male and female flowers grow on separate trees; you need both, or a grafted self-fertile kind.', 'Opossums, deer and raccoons spread the seed and the fruit is named from the Powhatan word pessamin.', 'Folklore reads the winter from the seed: split it and the white shape inside is a spoon, knife or fork.'] },
  { id: 'mulberry', name: 'Red Mulberry', sci: 'Morus rubra', family: 'Moraceae (fig family)', biomes: ['temperate', 'prairie', 'wetland'], soils: ['alfisol', 'mollisol', 'compost'], ph: [5.5, 7.5], water: 'med', sun: 'part', shape: 'spreading', log: 'oak', leaf: '#4a8a30', fruitColor: '#4a1a4a', height: [4, 6], grow: 360, seed: 'mulberry seeds', fruit: { name: 'mulberries', price: 3 },
    teach: 'The fruit is a cluster of tiny drupes, each from one flower, like a blackberry on a tree. Every bird for a mile knows the day they ripen; plant one as a decoy and your cherries may survive.',
    facts: ['Silkworms eat only mulberry leaves, the white species; Britain tried to start a silk industry and planted the wrong one.', 'The fruit stains everything purple; never park under it.', 'Mulberry roots are shallow and wide, and it fruits on new wood so it forgives any pruning.'] },
  { id: 'fig', name: 'Common Fig', sci: 'Ficus carica', family: 'Moraceae (fig family)', biomes: ['desert', 'temperate'], soils: ['aridisol', 'alfisol', 'compost'], ph: [6.0, 8.0], water: 'low', sun: 'full', shape: 'spreading', log: 'tropical', leaf: '#5a8a3a', fruitColor: '#6a3a6a', height: [3, 4], grow: 360, seed: 'fig cuttings', fruit: { name: 'figs', price: 4 },
    teach: 'A fig is a flower turned inside out: hundreds of tiny flowers line the inside of the fruit, and in wild figs a wasp the size of a comma crawls in to pollinate them. Garden figs set fruit with no wasp at all.',
    facts: ['One of the first plants humans farmed, 11,000 years ago in the Jordan valley, before wheat.', 'It roots from a stick pushed in the ground: the easiest fruit tree to multiply.', 'Figs fruit twice: a small early crop on old wood, the main crop on new.'] },
  { id: 'pomegranate', name: 'Pomegranate', sci: 'Punica granatum', family: 'Lythraceae (loosestrife family)', biomes: ['desert'], soils: ['aridisol', 'sand_subsoil', 'compost'], ph: [5.5, 7.5], water: 'low', sun: 'full', shape: 'spreading', log: 'mesquite', leaf: '#4a8a3a', fruitColor: '#c02030', height: [3, 4], grow: 360, seed: 'pomegranate seeds', fruit: { name: 'pomegranates', price: 5 },
    teach: 'Built for drought and heat: leathery leaves, a rind like armour and six hundred juice-filled seeds inside. The name means seeded apple, and the grenade is named after it.',
    facts: ['Grown in Persia and Egypt 5,000 years ago; found in Tutankhamun\'s tomb.', 'The flowers are scarlet trumpets that hummingbirds visit.', 'Split fruit means irregular watering: a long dry spell then a soak swells the seeds faster than the rind can grow.'] },
  { id: 'olive', name: 'Olive', sci: 'Olea europaea', family: 'Oleaceae (olive family)', biomes: ['desert'], soils: ['aridisol', 'sand_subsoil', 'compost'], ph: [6.5, 8.5], water: 'low', sun: 'full', shape: 'spreading', log: 'mesquite', leaf: '#7a9a6a', fruitColor: '#3a4a2a', height: [3, 4], grow: 540, seed: 'olive pits', fruit: { name: 'olives', price: 4 },
    teach: 'Olives on the tree are inedibly bitter; curing in brine or lye is what makes them food. The oil is simply pressed juice. Some trees in the Mediterranean have fruited for two thousand years.',
    facts: ['The grey-green underside of the leaf reflects sun and cuts water loss.', 'It wants poor, stony, alkaline soil and resents rich ground.', 'The olive branch has meant peace since Noah\'s dove, because the tree takes decades to bear and nobody plants it in wartime.'] },
  { id: 'lemon', name: 'Lemon', sci: 'Citrus × limon', family: 'Rutaceae (citrus family)', biomes: ['desert', 'rainforest'], soils: ['aridisol', 'oxisol', 'compost'], ph: [5.5, 6.5], water: 'med', sun: 'full', shape: 'spreading', log: 'tropical', leaf: '#3a7a2a', fruitColor: '#f0e040', height: [3, 4], grow: 400, seed: 'lemon seeds', fruit: { name: 'lemons', price: 4 },
    teach: 'A lemon flowers and fruits all year in a warm climate, so a tree carries blossom, green fruit and ripe fruit at once. It is a hybrid of citron and bitter orange that arose in cultivation.',
    facts: ['Scurvy killed more sailors than battle until the Royal Navy issued lemon and lime juice: hence "limeys".', 'Citrus leaves show the soil: yellow between green veins means iron locked up by high pH.', 'A lemon pip grows a thorny tree that may take ten years to fruit; grafted trees fruit in two.'] },
  { id: 'orange', name: 'Sweet Orange', sci: 'Citrus × sinensis', family: 'Rutaceae (citrus family)', biomes: ['desert', 'rainforest'], soils: ['aridisol', 'oxisol', 'compost'], ph: [5.5, 6.5], water: 'med', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#2f7a2a', fruitColor: '#f09020', height: [3, 5], grow: 450, seed: 'orange seeds', fruit: { name: 'oranges', price: 4 },
    teach: 'Oranges are green when ripe in the tropics; the orange colour needs cool nights to break down the chlorophyll. Florida fruit is sometimes gassed with ethylene to look the way customers expect.',
    facts: ['Every seedless navel orange descends from one mutant branch found in Brazil in 1820.', 'Citrus greening, spread by a tiny psyllid, has halved Florida\'s crop; the fight is biological, with parasitic wasps.', 'Orange blossom is the classic honey plant of Spain and Florida.'] },
  { id: 'avocado', name: 'Avocado', sci: 'Persea americana', family: 'Lauraceae (laurel family)', biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [6.0, 6.5], water: 'med', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#2a6a2a', fruitColor: '#3a5a2a', height: [5, 7], grow: 480, seed: 'avocado stones', fruit: { name: 'avocados', price: 5 },
    teach: 'The fruit was made for giant ground sloths, which swallowed it whole and spread the huge seed. The sloths died out 13,000 years ago; people kept the tree going. Its flowers open as female one morning and male the next.',
    facts: ['Avocado roots rot in wet soil; it needs the best drainage of any fruit tree.', 'A Hass avocado tree in California, planted in 1926 from a seed, is the mother of every Hass on Earth.', 'It takes about 70 litres of water to grow one avocado.'] },
  { id: 'mango', name: 'Mango', sci: 'Mangifera indica', family: 'Anacardiaceae (cashew family)', biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [5.5, 7.5], water: 'med', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#2f6a2f', fruitColor: '#f0b030', height: [6, 8], grow: 540, seed: 'mango stones', fruit: { name: 'mangoes', price: 5 },
    teach: 'The most eaten fruit on Earth, from India, where trees 300 years old still bear. It is a cousin of poison ivy and cashew, and the sap can blister skin. A dry season triggers flowering; in constant wet it grows leaves and no fruit.',
    facts: ['A mango tree can carry 30,000 flowers for every fruit it ripens.', 'New leaves flush copper-red before turning green: a sunscreen while they are soft.', 'Grafted mangoes fruit in 3 years; seedlings in 8, and the fruit is a gamble.'] },
  { id: 'papaya', name: 'Papaya', sci: 'Carica papaya', family: 'Caricaceae', biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [5.5, 7.0], water: 'med', sun: 'full', shape: 'palm', log: 'palm', leaf: '#4a9a3a', fruitColor: '#f0a040', height: [3, 4], grow: 180, seed: 'papaya seeds', fruit: { name: 'papayas', price: 3 },
    teach: 'Not really a tree: a giant hollow-stemmed herb that fruits within a year of sowing and is worn out in four. The sap holds papain, an enzyme that digests protein; cooks use it to tenderise meat.',
    facts: ['Papayas come male, female or both; plant three seeds and keep the best.', 'Ringspot virus nearly wiped out Hawaii\'s crop; a virus-resistant papaya was the first genetically engineered fruit sold.', 'The seeds taste of pepper and can be dried and ground as a spice.'] },
  { id: 'guava', name: 'Guava', sci: 'Psidium guajava', family: 'Myrtaceae (myrtle family)', biomes: ['rainforest', 'wetland'], soils: ['oxisol', 'gley', 'compost'], ph: [5.0, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'tropical', leaf: '#3f8a3f', fruitColor: '#d8e060', height: [3, 4], grow: 300, seed: 'guava seeds', fruit: { name: 'guavas', price: 3 },
    teach: 'Five times the vitamin C of an orange, in a fruit that grows almost anywhere warm. Birds and bats spread it so well that in Hawaii and Africa it has become a weed of pasture.',
    facts: ['The bark peels smooth and coppery like a eucalyptus, a cousin.', 'Guava leaf tea is a traditional remedy for diarrhoea, and it does contain tannins that work.', 'Fruit flies lay in the ripening fruit; bag the fruit or pick it firm.'] },
  { id: 'serviceberry', name: 'Serviceberry (Saskatoon)', sci: 'Amelanchier alnifolia', family: 'Rosaceae (rose family)', biomes: ['boreal', 'prairie', 'temperate'], soils: ['spodosol', 'mollisol', 'alfisol', 'compost'], ph: [5.5, 7.5], water: 'med', sun: 'part', shape: 'tall', log: 'birch', leaf: '#4a8a4a', fruitColor: '#5a3a7a', height: [3, 5], grow: 300, seed: 'serviceberry seeds', fruit: { name: 'saskatoon berries', price: 4 },
    teach: 'The first tree to flower in the northern woods, white before the leaves, and the fruit that fed the Plains peoples all winter as pemmican: dried meat, fat and pounded berries. It fruits in the far north where nothing else will.',
    facts: ['The name comes from the blossom coinciding with the ground thawing enough for burials and services.', 'The berries taste of almond and blueberry; the seeds hold the almond flavour.', 'Cedar-apple rust spots the leaves where junipers grow nearby; the fungus needs both trees to complete its life.'] },
  { id: 'chokecherry', name: 'Chokecherry', sci: 'Prunus virginiana', family: 'Rosaceae (rose family)', biomes: ['boreal', 'prairie'], soils: ['spodosol', 'mollisol', 'compost'], ph: [5.5, 7.5], water: 'low', sun: 'full', shape: 'broad', log: 'birch', leaf: '#3f7a35', fruitColor: '#3a0a1a', height: [3, 4], grow: 300, seed: 'chokecherry stones', fruit: { name: 'chokecherries', price: 2 },
    teach: 'So astringent raw that it chokes you, and the best jelly in the north once cooked with sugar. The most widespread tree in North America, from Alaska to Mexico. Its wilted leaves make cyanide and poison cattle.',
    facts: ['Black knot fungus grows thick black galls on the branches; prune them out in winter and burn them.', 'Birds plant chokecherry along every fence line.', 'The Lakota dried the fruit, stones and all, into cakes for winter.'] },
  { id: 'crabapple', name: 'Crabapple', sci: 'Malus sylvestris', family: 'Rosaceae (rose family)', biomes: ['boreal', 'temperate', 'prairie'], soils: ['spodosol', 'alfisol', 'mollisol', 'compost'], ph: [5.5, 7.5], water: 'med', sun: 'full', shape: 'spreading', log: 'birch', leaf: '#4a8a3a', fruitColor: '#d04040', height: [3, 4], grow: 330, seed: 'crabapple pips', fruit: { name: 'crabapples', price: 2 },
    teach: 'The wild apple of Europe and the pollinator every orchard needs: one crabapple among the eating apples sets fruit on all of them. The fruit is sour and full of pectin, which is why crabapple jelly sets by itself.',
    facts: ['Cider makers add crabapple for the tannin that gives a dry cider its bite.', 'Flowering crabs are the toughest street trees in the north, shrugging off minus 40.', 'Deer, grouse and foxes eat the windfalls; the tree pays its pollinators and its planters.'] },
  // ---- 20 more fruit trees ----
  { id: 'starfruit', name: 'Starfruit (Carambola)', sci: 'Averrhoa carambola', family: 'Oxalidaceae (wood sorrel family)', biomes: ['rainforest', 'wetland'], soils: ['oxisol', 'gley', 'compost'], ph: [5.5, 6.5], water: 'high', sun: 'full', shape: 'spreading', log: 'tropical', leaf: '#4a9a3a', fruitColor: '#f0d040', height: [3, 5], grow: 300, seed: 'starfruit seeds', fruit: { name: 'starfruit', price: 6 },
    teach: 'Cut it across and every slice is a five-pointed star. The tree flowers and fruits on and off all year in the tropics, in sweet and sour types. Its leaves fold up at night and when the branch is shaken, like its cousin the wood sorrel.',
    facts: ['Starfruit is rich in oxalic acid; people with kidney disease must not eat it.', 'A mature tree can give 100 kg of fruit a year on branches that hang to the ground.', 'Fruit bats and birds spread the seed; the tree is native to Southeast Asia.'] },
  { id: 'lychee', name: 'Lychee', sci: 'Litchi chinensis', family: 'Sapindaceae (soapberry family)', biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [5.5, 7.0], water: 'med', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#2f6a2f', fruitColor: '#d83a4a', height: [5, 8], grow: 420, seed: 'lychee seeds', fruit: { name: 'lychees', price: 6 },
    teach: 'A knobbly red shell peels off to show a pearl of sweet translucent flesh. Lychee needs a cool dry winter to flower well; it has been grown in southern China for 2,000 years, and emperors had the fruit raced to court by horse relay.',
    facts: ['The seed loses viability within days of leaving the fruit; plant it fresh.', 'Trees take 5 to 10 years from seed to fruit, so growers graft or air-layer.', 'Unripe lychee contains hypoglycin, which has made hungry children ill in India.'] },
  { id: 'jackfruit', name: 'Jackfruit', sci: 'Artocarpus heterophyllus', family: 'Moraceae (mulberry family)', biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [5.5, 7.0], water: 'high', sun: 'full', shape: 'tall', log: 'tropical', leaf: '#3a7a2a', fruitColor: '#a8b840', height: [6, 9], grow: 480, seed: 'jackfruit seeds', fruit: { name: 'jackfruit', price: 8 },
    teach: 'The largest tree-borne fruit on Earth: up to 50 kg, growing straight off the trunk where the thick wood can hold it (cauliflory). The latex glues your fingers, so oil the knife. Unripe it cooks like pulled pork; ripe it tastes of banana and pineapple.',
    facts: ['One tree can yield 200 fruit a year, which is why it is a food-security crop in Bangladesh and Kerala.', 'Each fruit is hundreds of flowers fused together, a syncarp.', 'The seeds roast like chestnuts; the yellow heartwood dyes the robes of Buddhist monks.'] },
  { id: 'breadfruit', name: 'Breadfruit', sci: 'Artocarpus altilis', family: 'Moraceae (mulberry family)', biomes: ['rainforest', 'wetland'], soils: ['oxisol', 'gley', 'compost'], ph: [6.0, 7.5], water: 'high', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#3f8a3f', fruitColor: '#a8c850', height: [6, 9], grow: 480, seed: 'breadfruit root cuttings', fruit: { name: 'breadfruit', price: 5 },
    teach: 'A starchy fruit the size of a football that bakes to a bread-like crumb. Polynesians carried it across the Pacific in canoes 3,000 years ago; most cultivars are seedless and are grown from root suckers.',
    facts: ['HMS Bounty was carrying breadfruit saplings to the Caribbean when its crew mutinied in 1789.', 'A mature tree gives 150 to 200 fruit a year with almost no care.', 'The deeply lobed leaves can be 60 cm long.'] },
  { id: 'rambutan', name: 'Rambutan', sci: 'Nephelium lappaceum', family: 'Sapindaceae (soapberry family)', biomes: ['rainforest'], soils: ['oxisol', 'compost'], ph: [5.5, 6.5], water: 'high', sun: 'full', shape: 'spreading', log: 'tropical', leaf: '#3a8a3a', fruitColor: '#d84a3a', height: [4, 7], grow: 400, seed: 'rambutan seeds', fruit: { name: 'rambutans', price: 6 },
    teach: 'Rambut is Malay for hair: the red fruit bristles with soft spines, and inside is a grape-like lychee cousin. Flowers are mostly male or female on separate trees, so growers plant one male for every ten females.',
    facts: ['The spines are soft and harmless; they catch the eye of birds and monkeys.', 'The fruit does not store; it is eaten where it grows, in a season of a few weeks.', 'Press with both thumbs and the skin splits cleanly in half.'] },
  { id: 'soursop', name: 'Soursop (Graviola)', sci: 'Annona muricata', family: 'Annonaceae (custard apple family)', biomes: ['rainforest', 'wetland'], soils: ['oxisol', 'gley', 'compost'], ph: [5.5, 6.5], water: 'high', sun: 'part', shape: 'spreading', log: 'tropical', leaf: '#3a7a3a', fruitColor: '#6a9a3a', height: [3, 5], grow: 300, seed: 'soursop seeds', fruit: { name: 'soursops', price: 5 },
    teach: 'A soft green fruit covered in curved spines, with white fibrous flesh tasting of strawberry and pineapple with a sour edge. Beetles that crawl into the flowers at night pollinate it, so growers often hand-pollinate with a brush.',
    facts: ['Guanabana in Mexico, graviola in Brazil: the pulp makes the classic ice cream and juice.', 'Pawpaw, the temperate tree, is in the same family and has the same custard flesh.', 'The tree is small and short-lived, cropping three years from seed.'] },
  { id: 'tamarind', name: 'Tamarind', sci: 'Tamarindus indica', family: 'Fabaceae (pea family)', biomes: ['desert', 'rainforest'], soils: ['aridisol', 'oxisol', 'compost'], ph: [5.5, 7.5], water: 'low', sun: 'full', shape: 'spreading', log: 'mesquite', leaf: '#5a9a4a', fruitColor: '#8a6a3a', height: [5, 8], grow: 520, seed: 'tamarind seeds', fruit: { name: 'tamarind pods', price: 4 },
    teach: 'A huge long-lived legume with feathery leaves and brown pods full of sticky sour pulp that flavours Worcestershire sauce, pad thai and agua de tamarindo. As a legume it fixes nitrogen, though slowly.',
    facts: ['Native to tropical Africa, it reached India so long ago that its Arabic name means Indian date.', 'Trees live 200 years and fruit for most of them.', 'The pulp is 10 to 15 percent tartaric acid, the acid of grapes.'] },
  { id: 'medjool_date', name: 'Medjool Date Palm', sci: 'Phoenix dactylifera \'Medjool\'', family: 'Arecaceae (palm family)', biomes: ['desert'], soils: ['aridisol', 'sand_subsoil', 'compost'], ph: [7.0, 8.5], water: 'low', sun: 'full', shape: 'palm', log: 'palm', leaf: '#6a9a5a', fruitColor: '#8a4a2a', height: [6, 9], grow: 560, seed: 'Medjool date pits', fruit: { name: 'Medjool dates', price: 5 },
    teach: 'The staff of life of the Sahara and Arabia: a palm that wants its head in fire and its feet in water, meaning blazing sun with irrigation at the root. Trees are male or female; one male pollinates fifty females and growers climb to dust the pollen by hand.',
    facts: ['A palm can carry 100 kg of dates a year for a century.', 'Date palms were cultivated in Mesopotamia 6,000 years ago, among the first trees domesticated.', 'A 2,000-year-old seed from Masada was germinated in 2005; the palm, named Methuselah, is alive today.'] },
  { id: 'coconut', name: 'Coconut Palm', sci: 'Cocos nucifera', family: 'Arecaceae (palm family)', biomes: ['rainforest', 'wetland'], soils: ['sand_subsoil', 'gley', 'oxisol'], ph: [5.5, 8.0], water: 'high', sun: 'full', shape: 'palm', log: 'palm', leaf: '#5a9a4a', fruitColor: '#7a9a4a', height: [7, 9], grow: 560, seed: 'sprouting coconut', fruit: { name: 'coconuts', price: 4 },
    teach: 'The tree of a thousand uses. The nut floats for months and sprouts on any tropical beach, which is how it colonised every shore in the tropics. Water, milk, oil, coir fibre, timber, thatch and charcoal all come from one palm.',
    facts: ['The nut is a drupe like a peach; the hairy thing in the shop is the stone, pulled out of a thick husk.', 'A palm drops 50 to 80 nuts a year and keeps going for 80 years.', 'Coconut water was used as emergency intravenous fluid in the Pacific war.'] },
  { id: 'apricot', name: 'Apricot', sci: 'Prunus armeniaca', family: 'Rosaceae (rose family)', biomes: ['temperate', 'prairie'], soils: ['alfisol', 'mollisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#4a8a3a', fruitColor: '#f0a040', height: [3, 5], grow: 320, seed: 'apricot stones', fruit: { name: 'apricots', price: 4 },
    teach: 'It flowers early, often before the last frost, so apricots crop in continental climates with dry springs and fail in damp ones. Domesticated in China and carried west on the Silk Road; the Latin name wrongly credits Armenia.',
    facts: ['The kernel tastes of almond and contains amygdalin, which releases cyanide.', 'Dried apricots are sulphured to stay orange; unsulphured ones go brown and taste richer.', 'Hunza and Ladakh villages above 2,500 m live largely on apricots and their oil.'] },
  { id: 'quince', name: 'Quince', sci: 'Cydonia oblonga', family: 'Rosaceae (rose family)', biomes: ['temperate'], soils: ['alfisol', 'compost'], ph: [6.0, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#5a9a5a', fruitColor: '#e8d050', height: [3, 4], grow: 320, seed: 'quince seeds', fruit: { name: 'quinces', price: 4 },
    teach: 'A golden, fuzzy, rock-hard pear cousin, too astringent raw but rose-pink and perfumed when cooked. Membrillo paste, quince jelly and the first marmalades (marmelo is Portuguese for quince) all set firmly because the fruit is loaded with pectin.',
    facts: ['Most pear trees are grafted onto quince roots to keep them small.', 'One ripe quince scents a room for weeks.', 'It may be the golden apple of Greek myth; apples were not golden then.'] },
  { id: 'loquat', name: 'Loquat', sci: 'Eriobotrya japonica', family: 'Rosaceae (rose family)', biomes: ['temperate', 'desert'], soils: ['alfisol', 'aridisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'broad', log: 'oak', leaf: '#2f5a2f', fruitColor: '#f0a030', height: [3, 5], grow: 300, seed: 'loquat seeds', fruit: { name: 'loquats', price: 4 },
    teach: 'An evergreen with leathery dark leaves that flowers in autumn and ripens apricot-coloured fruit in spring, when nothing else is ripe. Chinese in origin, it is grown around the Mediterranean and in Californian backyards, where the birds get most of it.',
    facts: ['The flowers smell of almond and feed bees in November.', 'Loquat leaf syrup is a classic Chinese cough remedy.', 'Each fruit holds two or three big brown seeds; the flesh is thin but juicy.'] },
  { id: 'kumquat', name: 'Kumquat', sci: 'Citrus japonica', family: 'Rutaceae (citrus family)', biomes: ['temperate', 'desert'], soils: ['alfisol', 'aridisol', 'compost'], ph: [6.0, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#2f6a2f', fruitColor: '#f08020', height: [2, 3], grow: 280, seed: 'kumquat seeds', fruit: { name: 'kumquats', price: 5 },
    teach: 'The citrus you eat whole: the peel is sweet and the flesh sour, so pop one in and chew. It is the hardiest citrus, standing frost to -10 C by going dormant, which is why it fruits where oranges cannot.',
    facts: ['The name is Cantonese, gam gwat, golden orange.', 'Trees stay under 3 m and fruit heavily in pots.', 'Crossed with limes it gives the limequat, with mandarins the calamondin.'] },
  { id: 'lime', name: 'Lime', sci: 'Citrus x aurantiifolia', family: 'Rutaceae (citrus family)', biomes: ['rainforest', 'desert'], soils: ['oxisol', 'aridisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'spreading', log: 'tropical', leaf: '#3a8a3a', fruitColor: '#7ab040', height: [2, 4], grow: 300, seed: 'lime seeds', fruit: { name: 'limes', price: 4 },
    teach: 'A thorny little tree that fruits all year in the tropics. British sailors sucked limes against scurvy, which is why they were called limeys, though the lime has less vitamin C than the lemon it replaced.',
    facts: ['Lime juice plus sunlight gives a skin burn called the bartender\'s rash.', 'Key lime and Persian lime are different species; the Persian is seedless and bigger.', 'The flowers are small, white and smell like jasmine.'] },
  { id: 'grapefruit', name: 'Grapefruit', sci: 'Citrus x paradisi', family: 'Rutaceae (citrus family)', biomes: ['desert', 'rainforest'], soils: ['aridisol', 'oxisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#2f6a2f', fruitColor: '#f0c050', height: [4, 6], grow: 400, seed: 'grapefruit seeds', fruit: { name: 'grapefruit', price: 4 },
    teach: 'An accident: a pomelo crossed with a sweet orange in 18th-century Barbados. It grows in clusters like grapes, hence the name. The bitterness is naringin, which also blocks a liver enzyme and makes some medicines dangerous.',
    facts: ['Pink and red varieties were found as single mutant branches in Texas groves.', 'Trees are among the largest citrus, to 15 m.', 'Grapefruit needs heat to sweeten; cool-grown fruit stays sour.'] },
  { id: 'elderberry', name: 'American Elderberry', sci: 'Sambucus canadensis', family: 'Adoxaceae (moschatel family)', biomes: ['temperate', 'wetland', 'prairie'], soils: ['alfisol', 'gley', 'mollisol', 'compost'], ph: [5.5, 7.0], water: 'high', sun: 'part', shape: 'spreading', log: 'birch', leaf: '#4a8a3a', fruitColor: '#2a1a3a', height: [2, 4], grow: 220, seed: 'elderberry seeds', fruit: { name: 'elderberries', price: 3 },
    teach: 'Flat plates of creamy flowers in June become drooping heads of black berries by August. Flowers make cordial and fritters; cooked berries make syrup and wine. Raw berries, leaves and stems hold cyanide-making glycosides, so always cook them.',
    facts: ['The hollow stems were made into flutes and pea-shooters; sambuca is Greek for a stringed instrument.', 'Forty-five species of birds eat the berries.', 'It suckers into thickets along ditches and fence lines and can be cut to the ground every few years.'] },
  { id: 'hawthorn', name: 'Downy Hawthorn', sci: 'Crataegus mollis', family: 'Rosaceae (rose family)', biomes: ['temperate', 'prairie'], soils: ['alfisol', 'mollisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#3f7a2f', fruitColor: '#c82a2a', height: [3, 5], grow: 320, seed: 'haw seeds', fruit: { name: 'haws', price: 3 },
    teach: 'The May tree: white blossom, then red haws that taste of over-ripe apple. Its thorns made it the hedging plant of Europe (haw means hedge) and dense cover for nesting birds. The haws contain compounds doctors still use for heart failure.',
    facts: ['Seeds need two winters in the ground to germinate.', 'There are hundreds of hawthorn species and botanists argue about every one.', 'Haw jelly sets well and goes with game.'] },
  { id: 'mountain_ash', name: 'American Mountain Ash (Rowan)', sci: 'Sorbus americana', family: 'Rosaceae (rose family)', biomes: ['boreal'], soils: ['spodosol', 'compost'], ph: [4.5, 6.5], water: 'med', sun: 'full', shape: 'tall', log: 'birch', leaf: '#4a8a4a', fruitColor: '#e83a2a', height: [4, 6], grow: 300, seed: 'rowan seeds', fruit: { name: 'rowan berries', price: 3 },
    teach: 'Not an ash at all but a rose relative with feathery leaves and blazing orange-red berry clusters that feed waxwings and grosbeaks through the first snows. The berries are bitter until frost, then make a tart jelly for venison.',
    facts: ['Rowan was planted by doors in Scotland to keep witches away.', 'Moose and deer browse it hard, which is why big trees are rare.', 'Sorbic acid, the food preservative, was first isolated from rowan berries.'] },
  { id: 'highbush_cranberry', name: 'Highbush Cranberry', sci: 'Viburnum trilobum', family: 'Adoxaceae (moschatel family)', biomes: ['boreal', 'wetland'], soils: ['spodosol', 'gley', 'histosol', 'compost'], ph: [5.0, 7.0], water: 'high', sun: 'part', shape: 'spreading', log: 'birch', leaf: '#4a8a3a', fruitColor: '#d82a2a', height: [2, 3], grow: 240, seed: 'viburnum seeds', fruit: { name: 'highbush cranberries', price: 3 },
    teach: 'Not a cranberry but a viburnum whose scarlet berries taste much the same and hang on all winter. Lacy white flower heads in spring, maple-shaped leaves that go wine-red in autumn, and fruit for grouse and waxwings when nothing else is left.',
    facts: ['The fruit smells of dirty socks when cooked; the jelly tastes wonderful.', 'Cree and Ojibwe people stored the berries frozen on the bush.', 'The big outer flowers in each cluster are sterile show flowers to pull in insects.'] },
  { id: 'jujube', name: 'Jujube (Chinese Date)', sci: 'Ziziphus jujuba', family: 'Rhamnaceae (buckthorn family)', biomes: ['desert', 'prairie'], soils: ['aridisol', 'sand_subsoil', 'mollisol', 'compost'], ph: [6.0, 8.5], water: 'low', sun: 'full', shape: 'spreading', log: 'mesquite', leaf: '#5a9a4a', fruitColor: '#8a3a2a', height: [3, 5], grow: 340, seed: 'jujube stones', fruit: { name: 'jujubes', price: 4 },
    teach: 'A thorny drought-proof tree whose fruit is crisp like an apple when yellow-green and chewy like a date once it wrinkles red-brown. Grown in China for 4,000 years, it shrugs off heat, salt and poor soil that kill most fruit trees.',
    facts: ['Zig-zag branches carry paired spines, one straight and one hooked.', 'Jujube is a traditional sleep aid; the seeds are in many Chinese medicines.', 'Trees fruit in their second or third year and live for centuries.'] },
  // ---------- America's most-grown orchard and nut trees ----------
  { id: 'almond', name: 'Almond', sci: 'Prunus dulcis', family: 'Rosaceae (rose family)', biomes: ['desert', 'prairie', 'temperate'], soils: ['aridisol', 'mollisol', 'alfisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#5a9a48', fruitColor: '#c8a878', height: [3, 4], grow: 400, seed: 'almond kernels', fruit: { name: 'almonds', price: 5 },
    teach: 'America\'s biggest tree crop by far: 1.4 million acres in California\'s Central Valley grow 80 percent of the world\'s almonds. The nut is the seed of a peach-like fruit whose dry, leathery flesh splits open on the tree. Almonds flower in February before the leaves, and two-thirds of all the honeybee hives in the United States are trucked in to pollinate them, the largest managed pollination event on Earth.',
    facts: ['Wild almonds are bitter and poisonous with cyanide; a single sweet mutation made the crop.', 'Each nut takes about 12 litres of irrigation water, which is why almonds dominate California\'s water debates.', 'Self-fertile varieties like Independence need no bees and are spreading fast.'] },
  { id: 'pistachio', name: 'Pistachio', sci: 'Pistacia vera', family: 'Anacardiaceae (cashew family)', biomes: ['desert'], soils: ['aridisol', 'sand_subsoil', 'compost'], ph: [7.0, 8.0], water: 'low', sun: 'full', shape: 'spreading', log: 'mesquite', leaf: '#6a9a58', fruitColor: '#d8a0a0', height: [3, 4], grow: 480, seed: 'pistachio nuts', fruit: { name: 'pistachios', price: 6 },
    teach: 'A desert tree from Iran that shrugs off salt, drought and alkaline soil but needs 1,000 hours of winter chill and a blazing summer. Trees are male or female and the wind, not bees, carries the pollen. The shell splits with an audible pop as the kernel swells. California planted its first commercial orchard in 1976 and now has 460,000 acres, second only to Iran.',
    facts: ['Trees bear heavily one year and lightly the next, a habit called alternate bearing.', 'The pink and green colours of the kernel are anthocyanin and chlorophyll.', 'A pistachio tree lives 300 years and takes 7 to bear its first nut.'] },
  { id: 'pecan', name: 'Pecan', sci: 'Carya illinoinensis', family: 'Juglandaceae (walnut family)', biomes: ['temperate', 'prairie', 'wetland'], soils: ['alfisol', 'mollisol', 'histosol', 'compost'], ph: [6.0, 7.0], water: 'high', sun: 'full', shape: 'tall', log: 'oak', leaf: '#4a8a3a', fruitColor: '#6a4a2a', height: [7, 9], grow: 540, seed: 'pecans', fruit: { name: 'pecans', price: 5 },
    teach: 'The only major nut tree native to North America, a hickory of the Mississippi and Texas river bottoms, where it grows 40 metres tall and lives three centuries. Native peoples ground pecans into a milk, and the name is Algonquian for a nut that needs a stone to crack. Georgia, New Mexico and Texas lead some 400,000 US acres.',
    facts: ['A pecan sheds its pollen before or after its own flowers are ready, so two varieties are needed.', 'The green husk splits into four and the nuts are shaken down with a mechanical tree shaker.', 'Thomas Jefferson planted pecans at Monticello and sent some to George Washington.'] },
  { id: 'walnut', name: 'English Walnut', sci: 'Juglans regia', family: 'Juglandaceae (walnut family)', biomes: ['temperate', 'prairie'], soils: ['alfisol', 'mollisol', 'compost'], ph: [6.0, 7.5], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#4a7a3a', fruitColor: '#5a7a3a', height: [5, 7], grow: 520, seed: 'walnuts', fruit: { name: 'walnuts', price: 5 },
    teach: 'A Persian tree carried west by Rome and east along the Silk Road; "English" only because English ships traded it. California grows nearly all of the 375,000 US acres, on orchards grafted onto native black walnut roots. The green husk stains hands brown for a week; the dye was once used for hair and cloth. The brain-shaped kernel earned it a reputation as a cure for headaches.',
    facts: ['Walnut roots and leaves release juglone, a chemical that kills tomatoes and many plants beneath the tree.', 'The nuts fall in their husks and are hulled, washed and dried within a day to keep the kernels pale.', 'Walnut is the finest furniture and gunstock wood in the temperate world.'] },
  { id: 'hazelnut', name: 'Hazelnut', sci: 'Corylus avellana', family: 'Betulaceae (birch family)', biomes: ['temperate', 'boreal'], soils: ['alfisol', 'spodosol', 'compost'], ph: [6.0, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'birch', leaf: '#4a8a40', fruitColor: '#a87040', height: [3, 4], grow: 420, seed: 'hazelnuts', fruit: { name: 'hazelnuts', price: 4 },
    teach: 'A shrubby tree that flowers in the dead of winter: yellow catkins shed pollen on the wind in January while the tiny red female flowers wait on the twigs. Oregon\'s Willamette Valley grows 99 percent of the American crop on about 90,000 acres, and a blight from the East Coast nearly wiped it out before resistant varieties were bred at Oregon State.',
    facts: ['Filbert, hazel and cobnut are all the same nut; "filbert" comes from St Philibert\'s day, when they ripen.', 'The nuts drop to the ground and are swept up by machines in October.', 'Turkey grows three-quarters of the world\'s hazelnuts, most of it for chocolate spread.'] },
  { id: 'mandarin', name: 'Mandarin Orange', sci: 'Citrus reticulata', family: 'Rutaceae (citrus family)', biomes: ['desert', 'rainforest'], soils: ['aridisol', 'oxisol', 'sand_subsoil', 'compost'], ph: [5.5, 6.5], water: 'med', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#2f7a2a', fruitColor: '#f08020', height: [3, 4], grow: 420, seed: 'mandarin seeds', fruit: { name: 'mandarins', price: 4 },
    teach: 'The small, loose-skinned citrus behind clementines, satsumas and tangerines, and one of the three wild ancestors of all citrus with the pomelo and the citron: a sweet orange is simply a mandarin crossed with a pomelo. Seedless "Cuties" grown on 70,000 California acres are seedless only if bees cannot carry pollen in from other citrus, so growers net the trees or pay beekeepers to stay away.',
    facts: ['Satsumas ripen in November and survive frosts that kill oranges, so they grow along the Gulf Coast.', 'The peel is loose because the segments are held by a spongy pith that dries as the fruit ripens.', 'A mandarin tree can carry more than 1,000 fruit.'] },
  { id: 'nectarine', name: 'Nectarine', sci: 'Prunus persica var. nucipersica', family: 'Rosaceae (rose family)', biomes: ['temperate', 'prairie', 'desert'], soils: ['alfisol', 'mollisol', 'aridisol', 'compost'], ph: [6.0, 7.0], water: 'med', sun: 'full', shape: 'spreading', log: 'oak', leaf: '#5a9a3a', fruitColor: '#d84040', height: [3, 4], grow: 360, seed: 'nectarine pits', fruit: { name: 'nectarines', price: 4 },
    teach: 'A peach with one recessive gene switched off, the one that grows the fuzz. Nectarines turn up on peach trees as bud sports and peach pits sometimes grow nectarines. The smooth skin bruises and rots more easily, so they were rare until cold storage; now California grows 17,000 acres, nearly all of the American crop.',
    facts: ['The name comes from nectar, the drink of the Greek gods.', 'Like peaches they need 600 to 900 chill hours and are pruned to an open vase so sun reaches every fruit.', 'Thinning the fruit to one every 15 centimetres in spring makes the rest twice the size.'] },
  { id: 'macadamia', name: 'Macadamia', sci: 'Macadamia integrifolia', family: 'Proteaceae', biomes: ['rainforest'], soils: ['oxisol', 'alfisol', 'compost'], ph: [5.5, 6.5], water: 'med', sun: 'full', shape: 'broad', log: 'tropical', leaf: '#2f6a2a', fruitColor: '#6a4a2a', height: [4, 6], grow: 560, seed: 'macadamia nuts', fruit: { name: 'macadamias', price: 6 },
    teach: 'An Australian rainforest tree whose nut has the hardest shell of any: 20 kilograms of pressure to crack it, which is why it was the last major nut to be farmed. Hawaii planted it on old sugar land in the 1920s and grows about 17,000 acres on the Big Island\'s volcanic slopes. The nuts drop when ripe and are gathered from the ground.',
    facts: ['The kernel is 75 percent oil, the richest of all nuts.', 'Macadamias are poisonous to dogs, though nobody knows which compound does it.', 'The tree is a protea, kin to South Africa\'s king protea and the Australian banksia, a family that evolved on Gondwana.'] }
];
BC.TREE_BY_ID = {};
BC.TREES.forEach(t => { BC.TREE_BY_ID[t.id] = t; });
